def solve(payload):
    points = payload["points"]
    if len(points) < 2:
        return {"error": "too_few_points"}
    if any(right[0] <= left[0] for left, right in zip(points, points[1:])):
        return {"error": "time_order"}
    import math
    energy = math.fsum((right[0] - left[0]) * (left[1] + right[1]) / 2 for left, right in zip(points, points[1:]))
    return {"energy_joules": energy}

